-- 002_seed_units_1_3.sql
-- Syncs the approved curriculum architecture into tamakkun-lughati.
-- Idempotent: lesson codes and unit codes are upserted.

insert into public.course_units(code,unit_order,title,goal,expected_outcome,measurable_objectives,mastery_threshold,minimum_core_objective_percent,is_published,content_version)
values ('U1',1,'حقوق وواجبات','أن يفهم الطالب الحقوق والواجبات في النصوص المسموعة والمقروءة، ويطبق مهارات الوحدة اللغوية والكتابية والشفهية في سياقات جديدة.','طالب قادر على قراءة قضايا الحقوق والواجبات وتحليلها، وتوظيف مهارات الوحدة اللغوية في الكتابة والتواصل.','["يستخرج الحقوق والواجبات والقيم من نصوص الوحدة مستندًا إلى شواهد.","يميز الأفكار الرئيسة والفرعية ويستخدم الأسئلة لزيادة التركيز والفهم.","يكتب الألف اللينة في الأفعال الثلاثية كتابة صحيحة ويعلل الرسم.","يرسم (ل، لا) بخط الرقعة رسمًا صحيحًا.","يتعرف اسم الفاعل ويصوغه ويوظفه.","يتعرف أسلوب القسم ويحدد أركانه ويوظفه.","يتعرف الحال وصاحبها ويوظف الحال في جملة صحيحة.","يخطط لخطبة محفلية ويكتبها ويراجعها.","يلقي خطبة قصيرة بوضوح وتسلسل وثقة."]'::jsonb,85,80,true,'curriculum-v1')
on conflict(code) do update set unit_order=excluded.unit_order,title=excluded.title,goal=excluded.goal,expected_outcome=excluded.expected_outcome,measurable_objectives=excluded.measurable_objectives,mastery_threshold=85,minimum_core_objective_percent=80,is_published=true,content_version='curriculum-v1',updated_at=now();

insert into public.course_units(code,unit_order,title,goal,expected_outcome,measurable_objectives,mastery_threshold,minimum_core_objective_percent,is_published,content_version)
values ('U2',2,'أعلام معاصرون','أن يحلل الطالب سير أعلام معاصرين ونصوصًا مرتبطة بهم، ويطبق مهارات الوحدة في القراءة والصرف والأسلوب والنحو والكتابة.','طالب قادر على قراءة السيرة وتحليل الشخصية وكتابة سيرة غيرية موظفًا مهارات لغوية صحيحة.','["يفهم نصوص الأعلام المسموعة والمقروءة ويصنف أفكارها.","يستخدم الرسوم الإيضاحية لزيادة التركيز والفهم.","يكتب الألف اللينة في الأفعال غير الثلاثية كتابة صحيحة.","يرسم (ك، م) بخط الرقعة رسمًا صحيحًا.","يتعرف اسم المفعول ويصوغه ويوظفه.","يتعرف أسلوب الشرط ويحدد أركانه ويوظفه.","يتعرف التمييز ويميزه ويوظفه.","يكتب سيرة غيرية منظمة من معلومات موثقة.","يعرض رأيه بلغة مهذبة ودقيقة."]'::jsonb,85,80,true,'curriculum-v1')
on conflict(code) do update set unit_order=excluded.unit_order,title=excluded.title,goal=excluded.goal,expected_outcome=excluded.expected_outcome,measurable_objectives=excluded.measurable_objectives,mastery_threshold=85,minimum_core_objective_percent=80,is_published=true,content_version='curriculum-v1',updated_at=now();

insert into public.course_units(code,unit_order,title,goal,expected_outcome,measurable_objectives,mastery_threshold,minimum_core_objective_percent,is_published,content_version)
values ('U3',3,'أمن وازدهار','أن يفهم الطالب علاقة الأمن بالازدهار والمسؤولية المجتمعية، ويحلل نصوص الوحدة ويطبق مهاراتها اللغوية والكتابية والشفهية.','طالب قادر على تحليل قضايا الأمن والمسؤولية وتوظيف مهارات الوحدة في الكتابة والحوار.','["يفهم نصوص الأمن والازدهار ويحلل الأفكار والقيم والأدلة.","يستخدم إستراتيجية زيادة التركيز والفهم في نصوص طويلة.","يرسم الكلمات الموصولة خطًّا وفق القاعدة المستهدفة.","يرسم الحرف (هـ) بخط الرقعة رسمًا صحيحًا.","يتعرف صيغ المبالغة ويميزها ويوظفها.","يستخدم أسلوب التفضيل بصورة صحيحة.","يتعرف المستثنى ويحدد أركانه ويوظفه.","يبسط موجزًا إلى نص مترابط محافظًا على الفكرة.","يتحاور مع المجموعة وفق آداب الحوار."]'::jsonb,85,80,true,'curriculum-v1')
on conflict(code) do update set unit_order=excluded.unit_order,title=excluded.title,goal=excluded.goal,expected_outcome=excluded.expected_outcome,measurable_objectives=excluded.measurable_objectives,mastery_threshold=85,minimum_core_objective_percent=80,is_published=true,content_version='curriculum-v1',updated_at=now();

